from rdkit import Chem
try:
 import selfies as sf
 print('selfies_available', True)
 xs=['[C][C][N][Branch1][Ring1][C][C][C][C]','[C][S][=Branch1][C][=O][=Branch1][C][=O][Cl]','[Cl][C][Cl]','[O][C][C][=C][O][C][Branch1][C][Cl][=N][Ring1][=Branch1]','[Cl-1]','[NH4+1]']
 for x in xs:
  smi=sf.decoder(x)
  print(x,'=>',smi, 'canonical=>', Chem.MolToSmiles(Chem.MolFromSmiles(smi)) if Chem.MolFromSmiles(smi) else None)
except Exception as e: print(type(e).__name__,e)
